//! Property-based tests for kataba-core.
//!
//! These tests verify fundamental invariants of the editor core using
//! random inputs generated by proptest.

use kataba_core::assoc::Assoc;
use kataba_core::change::{ChangeSet, Operation};
use kataba_core::encoding::PositionEncoding;
use kataba_core::point::Point;
use kataba_core::rope::Rope;
use kataba_core::selection::Selection;
use kataba_core::transaction::Transaction;
use proptest::prelude::*;

fn random_string(rng: &mut proptest::test_runner::TestRng, len: usize) -> String {
    let mut s = String::with_capacity(len);
    for _ in 0..len {
        let ch = (b'a' + ((rng.next_u32() as u8) % 26)) as char;
        s.push(ch);
    }
    s
}

fn random_changeset_for_rope(rope: &Rope, rng: &mut proptest::test_runner::TestRng) -> ChangeSet {
    let mut changes = Vec::new();
    let mut pos = 0usize;
    let total = rope.len();
    while pos < total {
        let rem = total - pos;
        let choice = (rng.next_u32() % 3) as usize;
        match choice {
            0 => {
                // retain 1..=rem
                let take = 1 + ((rng.next_u32() as usize) % rem);
                changes.push(Operation::Retain(take));
                pos += take;
            }
            1 => {
                // delete 1..=rem
                let take = 1 + ((rng.next_u32() as usize) % rem);
                changes.push(Operation::Delete(take));
                pos += take;
            }
            2 => {
                // insert random string
                let ins_len = (rng.next_u32() as usize) % 6;
                let ins = random_string(rng, ins_len);
                if !ins.is_empty() {
                    changes.push(Operation::Insert(ins.into()));
                }
            }
            _ => {}
        }
    }
    ChangeSet::new(changes)
}

proptest! {
    /// Applying a change set and then its inversion should restore the original rope.
    #[test]
    fn apply_invert_is_identity(
        original in "[a-z]{5,50}",
        insert_pos in 0..30usize,
        insert_text in "[a-z]{0,10}",
    ) {
        let mut rope = Rope::from_str(&original);
        let pos = insert_pos.min(original.len());
        let changes = ChangeSet::new(vec![
            Operation::Retain(pos),
            Operation::Insert(insert_text.clone().into()),
            Operation::Retain(original.len() - pos),
        ]);
        let original_len = rope.len();
        assert!(changes.apply(&mut rope));
        let inverted = changes.invert(&Rope::from_str(&original));
        let mut restored = rope.clone();
        assert!(inverted.apply(&mut restored));
        prop_assert_eq!(restored.len(), original_len);
    }

    /// An empty change set should not modify the rope.
    #[test]
    fn empty_change_set_is_identity(text in "[a-z]{0,50}") {
        let mut rope = Rope::from_str(&text);
        let original_len = rope.len();
        let empty = ChangeSet::from_doc(&rope);
        prop_assert!(empty.apply(&mut rope));
        prop_assert_eq!(rope.len(), original_len);
    }

    /// Composing two change sets and applying the result should equal
    /// applying each change set sequentially.
    #[test]
    fn compose_equals_sequential_apply(
        text in "[a-z]{0,30}",
    ) {
        let mut rng = proptest::test_runner::TestRng::deterministic_rng(
            proptest::test_runner::RngAlgorithm::default(),
        );
        let rope0 = Rope::from_str(&text);
        let c1 = random_changeset_for_rope(&rope0, &mut rng);
        let mut rope1 = rope0.clone();
        prop_assert!(c1.apply(&mut rope1));
        let c2 = random_changeset_for_rope(&rope1, &mut rng);
        let mut rope2 = rope1.clone();
        prop_assert!(c2.apply(&mut rope2));
        let c = c1.clone().compose(c2.clone());
        let mut rope_c = rope0.clone();
        prop_assert!(c.apply(&mut rope_c));
        prop_assert_eq!(rope_c, rope2);
    }

    /// A transaction with no changes should not modify the rope.
    #[test]
    fn empty_transaction_is_identity(text in "[a-z]{0,50}") {
        let mut rope = Rope::from_str(&text);
        let original_len = rope.len();
        let tx = Transaction::empty();
        let mut sel = Selection::default();
        tx.apply(&mut rope, &mut sel);
        prop_assert_eq!(rope.len(), original_len);
    }

    /// Point round-trip: char -> Point -> char should be identity.
    #[test]
    fn point_round_trip(
        text in "[a-z\n]{1,100}",
        char_idx in 0..100usize,
    ) {
        let rope = Rope::from_str(&text);
        let idx = char_idx.min(rope.len());
        let point = rope.char_to_point(idx, PositionEncoding::Utf16);
        let back = rope.point_to_char(point, PositionEncoding::Utf16);
        prop_assert_eq!(back, idx);
    }

    /// Point round-trip for UTF-8 encoding.
    #[test]
    fn point_round_trip_utf8(
        text in "[a-z\n]{1,100}",
        char_idx in 0..100usize,
    ) {
        let rope = Rope::from_str(&text);
        let idx = char_idx.min(rope.len());
        let point = rope.char_to_point(idx, PositionEncoding::Utf8);
        let back = rope.point_to_char(point, PositionEncoding::Utf8);
        prop_assert_eq!(back, idx);
    }

    /// Point round-trip for UTF-32 encoding.
    #[test]
    fn point_round_trip_utf32(
        text in "[a-z\n]{1,100}",
        char_idx in 0..100usize,
    ) {
        let rope = Rope::from_str(&text);
        let idx = char_idx.min(rope.len());
        let point = rope.char_to_point(idx, PositionEncoding::Utf32);
        let back = rope.point_to_char(point, PositionEncoding::Utf32);
        prop_assert_eq!(back, idx);
    }

    /// Assoc::BeforeSticky: position on insert boundary stays put.
    #[test]
    fn assoc_before_sticky_on_insert_boundary(
        original in "[a-z]{1,20}",
        insert_pos in 0..20usize,
        insert_text in "[a-z]{1,10}",
    ) {
        let pos = insert_pos.min(original.len());
        let changes = ChangeSet::new(vec![
            Operation::Retain(pos),
            Operation::Insert(insert_text.clone().into()),
            Operation::Retain(original.len() - pos),
        ]);
        // Position exactly at the insert boundary
        let mapped = changes.map_position(pos, Assoc::BeforeSticky);
        // BeforeSticky should stay at the same offset (before the inserted text)
        prop_assert_eq!(mapped, pos);
    }

    /// Assoc::AfterSticky: position on insert boundary moves past (Helix parity).
    #[test]
    fn assoc_after_sticky_on_insert_boundary(
        original in "[a-z]{1,20}",
        insert_pos in 0..20usize,
        insert_text in "[a-z]{1,10}",
    ) {
        let pos = insert_pos.min(original.len());
        let changes = ChangeSet::new(vec![
            Operation::Retain(pos),
            Operation::Insert(insert_text.clone().into()),
            Operation::Retain(original.len() - pos),
        ]);
        // Position exactly at the insert boundary
        let mapped = changes.map_position(pos, Assoc::AfterSticky);
        // AfterSticky moves past inserted text (Helix insert_offset semantics)
        prop_assert_eq!(mapped, pos + insert_text.chars().count());
    }

    /// Assoc::Before: position on retain boundary maps to lower offset.
    /// Note: with consecutive Retains, the boundary is passed through, so Before=After=pos.
    #[test]
    fn assoc_before_on_retain_boundary(
        original in "[a-z]{1,20}",
        retain_len in 1..20usize,
    ) {
        let pos = retain_len.min(original.len());
        let changes = ChangeSet::new(vec![
            Operation::Retain(pos),
            Operation::Retain(original.len() - pos),
        ]);
        // Position exactly at the retain boundary (passed to next Retain)
        let mapped = changes.map_position(pos, Assoc::Before);
        // Before behaves like After for consecutive Retains
        prop_assert_eq!(mapped, pos);
    }

    /// Assoc::After: position on retain boundary maps to higher offset.
    #[test]
    fn assoc_after_on_retain_boundary(
        original in "[a-z]{1,20}",
        retain_len in 1..20usize,
    ) {
        let pos = retain_len.min(original.len());
        let changes = ChangeSet::new(vec![
            Operation::Retain(pos),
            Operation::Retain(original.len() - pos),
        ]);
        // Position exactly at the retain boundary
        let mapped = changes.map_position(pos, Assoc::After);
        // After should map to higher offset
        prop_assert_eq!(mapped, pos);
    }

    /// Position inside delete region collapses to start.
    #[test]
    fn assoc_delete_region_collapses(
        original in "[a-z]{5,20}",
        delete_start in 0..15usize,
        delete_len in 1..10usize,
        pos_in_delete in 0..10usize,
    ) {
        let start = delete_start.min(original.len().saturating_sub(1));
        let len = delete_len.min(original.len() - start);
        let pos = (start + pos_in_delete).min(start + len);
        let changes = ChangeSet::new(vec![
            Operation::Retain(start),
            Operation::Delete(len),
            Operation::Retain(original.len() - start - len),
        ]);
        // Position inside delete region
        let mapped_before = changes.map_position(pos, Assoc::Before);
        let mapped_after = changes.map_position(pos, Assoc::After);
        // Both should collapse to start of deleted region
        prop_assert_eq!(mapped_before, start);
        prop_assert_eq!(mapped_after, start);
    }

    /// Position inside insert region moves past inserted text.
    #[test]
    fn assoc_insert_region_moves_past(
        original in "[a-z]{1,20}",
        insert_pos in 0..20usize,
        insert_text in "[a-z]{1,10}",
    ) {
        let pos = insert_pos.min(original.len());
        let ins_len = insert_text.chars().count();
        let changes = ChangeSet::new(vec![
            Operation::Retain(pos),
            Operation::Insert(insert_text.clone().into()),
            Operation::Retain(original.len() - pos),
        ]);
        // Position at the insert boundary (pos is where insert happens)
        // Before stays before insert, After moves past insert
        let mapped_before = changes.map_position(pos, Assoc::Before);
        let mapped_after = changes.map_position(pos, Assoc::After);
        // Before should stay at pos (before inserted text)
        prop_assert_eq!(mapped_before, pos);
        // After should move past inserted text
        prop_assert_eq!(mapped_after, pos + ins_len);
    }

    /// Pure transaction inversion restores the document without needing it (A1/A4).
    #[test]
    fn transaction_pure_invert_is_identity(
        original in "[a-z]{1,30}",
        from in 0..30usize,
        to in 0..30usize,
        replacement in "[a-z]{0,8}",
    ) {
        let doc = Rope::from_str(&original);
        let len = doc.len();
        let a = from.min(len);
        let b = to.min(len);
        let (f, t) = if a <= b { (a, b) } else { (b, a) };
        let rep = if replacement.is_empty() { None } else { Some(replacement.clone().into()) };
        let txn = Transaction::change(&doc, std::iter::once((f, t, rep)));
        prop_assert!(txn.is_pure());
        let inv = txn.invert().ok_or_else(|| proptest::test_runner::TestCaseError::fail("pure invert"))?;
        let mut doc1 = doc.clone();
        prop_assert!(txn.apply_doc(&mut doc1));
        prop_assert!(inv.apply_doc(&mut doc1));
        prop_assert_eq!(doc1, doc);
        // Double inversion round-trips the changeset.
        let again = inv.invert().ok_or_else(|| proptest::test_runner::TestCaseError::fail("double invert"))?;
        prop_assert_eq!(again.changes, txn.changes);
    }

    /// Pure composed transactions apply like sequential application and invert (A2/A4).
    #[test]
    fn transaction_compose_stays_pure(
        original in "[a-z]{1,30}",
        from1 in 0..30usize,
        to1 in 0..30usize,
        rep1 in "[a-z]{0,6}",
        from2 in 0..40usize,
        to2 in 0..40usize,
        rep2 in "[a-z]{0,6}",
    ) {
        let doc0 = Rope::from_str(&original);
        let len0 = doc0.len();
        let a = from1.min(len0);
        let b = to1.min(len0);
        let (f1, t1) = if a <= b { (a, b) } else { (b, a) };
        let r1 = if rep1.is_empty() { None } else { Some(rep1.clone().into()) };
        let txn1 = Transaction::change(&doc0, std::iter::once((f1, t1, r1)));
        let mut doc1 = doc0.clone();
        prop_assert!(txn1.apply_doc(&mut doc1));
        let len1 = doc1.len();
        let c = from2.min(len1);
        let d = to2.min(len1);
        let (f2, t2) = if c <= d { (c, d) } else { (d, c) };
        let r2 = if rep2.is_empty() { None } else { Some(rep2.clone().into()) };
        let txn2 = Transaction::change(&doc1, std::iter::once((f2, t2, r2)));
        let mut doc2 = doc1.clone();
        prop_assert!(txn2.apply_doc(&mut doc2));
        let composed = txn1.compose(txn2);
        prop_assert!(composed.is_pure());
        let mut doc_c = doc0.clone();
        prop_assert!(composed.apply_doc(&mut doc_c));
        prop_assert_eq!(doc_c.clone(), doc2);
        let inv = composed.invert().ok_or_else(|| proptest::test_runner::TestCaseError::fail("composed pure invert"))?;
        prop_assert!(inv.apply_doc(&mut doc_c));
        prop_assert_eq!(doc_c, doc0);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_apply_invert_simple() {
        let original = "hello";
        let mut rope = Rope::from_str(original);
        let changes = ChangeSet::new(vec![
            Operation::Retain(2),
            Operation::Insert("XY".into()),
            Operation::Retain(3),
        ]);
        assert!(changes.apply(&mut rope));
        assert_eq!(rope.len(), 7);
        let inverted = changes.invert(&Rope::from_str(original));
        let mut restored = rope.clone();
        assert!(inverted.apply(&mut restored));
        assert_eq!(restored.len(), 5);
    }

    #[test]
    fn test_point_round_trip_emoji() {
        let rope = Rope::from_str("a😀b");
        // char indices: 0='a', 1='😀', 2='b'
        let p0 = rope.char_to_point(0, PositionEncoding::Utf16);
        assert_eq!(p0, Point::new(0, 0));
        let p1 = rope.char_to_point(1, PositionEncoding::Utf16);
        assert_eq!(p1, Point::new(0, 1));
        let p2 = rope.char_to_point(2, PositionEncoding::Utf16);
        // '😀' takes 2 UTF-16 code units
        assert_eq!(p2, Point::new(0, 3));
        let p3 = rope.char_to_point(3, PositionEncoding::Utf16);
        assert_eq!(p3, Point::new(0, 4));
        
        // Round-trip
        assert_eq!(rope.point_to_char(p0, PositionEncoding::Utf16), 0);
        assert_eq!(rope.point_to_char(p1, PositionEncoding::Utf16), 1);
        assert_eq!(rope.point_to_char(p2, PositionEncoding::Utf16), 2);
        assert_eq!(rope.point_to_char(p3, PositionEncoding::Utf16), 3);
    }

    #[test]
    fn test_point_round_trip_cjk() {
        let rope = Rope::from_str("a中b");
        // '中' is U+4E2D, in BMP, takes 1 UTF-16 code unit
        let p0 = rope.char_to_point(0, PositionEncoding::Utf16);
        assert_eq!(p0, Point::new(0, 0));
        let p1 = rope.char_to_point(1, PositionEncoding::Utf16);
        assert_eq!(p1, Point::new(0, 1));
        let p2 = rope.char_to_point(2, PositionEncoding::Utf16);
        assert_eq!(p2, Point::new(0, 2));
        let p3 = rope.char_to_point(3, PositionEncoding::Utf16);
        assert_eq!(p3, Point::new(0, 3));
        
        // Round-trip
        assert_eq!(rope.point_to_char(p0, PositionEncoding::Utf16), 0);
        assert_eq!(rope.point_to_char(p1, PositionEncoding::Utf16), 1);
        assert_eq!(rope.point_to_char(p2, PositionEncoding::Utf16), 2);
        assert_eq!(rope.point_to_char(p3, PositionEncoding::Utf16), 3);
    }

    #[test]
    fn test_point_round_trip_multiline() {
        let rope = Rope::from_str("hello\nworld");
        // Line 0: "hello" (5 chars)
        // Line 1: "world" (5 chars)
        let p0 = rope.char_to_point(0, PositionEncoding::Utf16);
        assert_eq!(p0, Point::new(0, 0));
        let p5 = rope.char_to_point(5, PositionEncoding::Utf16);
        assert_eq!(p5, Point::new(0, 5));
        let p6 = rope.char_to_point(6, PositionEncoding::Utf16); // '\n' is char 5, 'w' is char 6
        assert_eq!(p6, Point::new(1, 0));
        let p11 = rope.char_to_point(11, PositionEncoding::Utf16);
        assert_eq!(p11, Point::new(1, 5));
        
        // Round-trip
        assert_eq!(rope.point_to_char(p0, PositionEncoding::Utf16), 0);
        assert_eq!(rope.point_to_char(p5, PositionEncoding::Utf16), 5);
        assert_eq!(rope.point_to_char(p6, PositionEncoding::Utf16), 6);
        assert_eq!(rope.point_to_char(p11, PositionEncoding::Utf16), 11);
    }

    #[test]
    fn test_assoc_before_sticky_on_insert() {
        let changes = ChangeSet::new(vec![
            Operation::Retain(2),
            Operation::Insert("XY".into()),
            Operation::Retain(3),
        ]);
        // Position exactly at insert boundary (index 2)
        let mapped = changes.map_position(2, Assoc::BeforeSticky);
        // BeforeSticky should stay at offset 2 (before inserted text)
        assert_eq!(mapped, 2);
    }

    #[test]
    fn test_assoc_after_sticky_on_insert() {
        let changes = ChangeSet::new(vec![
            Operation::Retain(2),
            Operation::Insert("XY".into()),
            Operation::Retain(3),
        ]);
        // Position exactly at insert boundary (index 2)
        let mapped = changes.map_position(2, Assoc::AfterSticky);
        // AfterSticky moves past inserted text (Helix parity: 2 + 2 = 4)
        assert_eq!(mapped, 4);
    }

    #[test]
    fn test_assoc_delete_collapses() {
        let changes = ChangeSet::new(vec![
            Operation::Retain(1),
            Operation::Delete(3), // deletes "ell"
            Operation::Retain(1),
        ]);
        // Position inside delete region
        let mapped_before = changes.map_position(2, Assoc::Before);
        let mapped_after = changes.map_position(2, Assoc::After);
        // Both should collapse to start of deleted region (1)
        assert_eq!(mapped_before, 1);
        assert_eq!(mapped_after, 1);
    }

    #[test]
    fn test_assoc_insert_moves_past() {
        let changes = ChangeSet::new(vec![
            Operation::Retain(2),
            Operation::Insert("XY".into()),
            Operation::Retain(3),
        ]);
        // Position at insert boundary (non-sticky)
        let mapped_before = changes.map_position(2, Assoc::Before);
        let mapped_after = changes.map_position(2, Assoc::After);
        // Before stays before insert, After moves past
        assert_eq!(mapped_before, 2);
        assert_eq!(mapped_after, 4);
    }
}